$ErrorActionPreference = "Stop"

$ProjectRoot = "H:\MNTrapTeam\MNTrapTeam"
$Version = "4.4.2"

if (-not (Test-Path (Join-Path $ProjectRoot "mntrapteam"))) {
    throw "MNTrapTeam project not found at $ProjectRoot"
}

Write-Host "Installing MNTrapTeam $Version scoreboard scout tolerance update..."

$scorePayload = ""
$scoutPayload = ""

[IO.File]::WriteAllBytes(
    (Join-Path $ProjectRoot "mntrapteam\shootscoreboard_web.py"),
    [Convert]::FromBase64String($scorePayload)
)
Write-Host "Updated: mntrapteam\shootscoreboard_web.py"

[IO.File]::WriteAllBytes(
    (Join-Path $ProjectRoot "mntrapteam\recent_score_scout_cli.py"),
    [Convert]::FromBase64String($scoutPayload)
)
Write-Host "Updated: mntrapteam\recent_score_scout_cli.py"

Set-Content -Path (Join-Path $ProjectRoot "VERSION") -Value $Version -Encoding UTF8

$InitFile = Join-Path $ProjectRoot "mntrapteam\__init__.py"
if (Test-Path $InitFile) {
    $t = Get-Content $InitFile -Raw
    if ($t -match '__version__\s*=') {
        $t = [regex]::Replace(
            $t,
            '__version__\s*=\s*["''][^"'']+["'']',
            '__version__ = "4.4.2"',
            1
        )
    } else {
        $t = $t.TrimEnd() + "`r`n__version__ = `"4.4.2`"`r`n"
    }
    Set-Content -Path $InitFile -Value $t -Encoding UTF8
}

$GuiFile = Join-Path $ProjectRoot "mntrapteam\gui.py"
if (Test-Path $GuiFile) {
    $t = Get-Content $GuiFile -Raw
    $t = [regex]::Replace($t, 'MNTrapTeam \d+\.\d+\.\d+', 'MNTrapTeam 4.4.2', 1)
    Set-Content -Path $GuiFile -Value $t -Encoding UTF8
}

Set-Location $ProjectRoot

Write-Host "Checking module syntax..."
& ".\.venv\Scripts\python.exe" -m py_compile `
    ".\mntrapteam\shootscoreboard_web.py" `
    ".\mntrapteam\recent_score_scout_cli.py"

if ($LASTEXITCODE -ne 0) {
    throw "Python syntax check failed."
}

Write-Host ""
Write-Host "MNTrapTeam 4.4.2 installed."
Write-Host "Common 16-yard event wording is now recognized."
Write-Host "Unsupported/malformed events are skipped without dropping the whole shoot."
Write-Host ""
Write-Host "Next:"
Write-Host '& ".\.venv\Scripts\python.exe" -m mntrapteam.recent_score_scout_cli preview --id-scan 1900:2300'
